		{"node":"n2","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0,"missed":1}
	]`
	_, err = ParseHeartbeats([]byte(input), receive)
	if err == nil {
		t.Fatalf("expected error for duplicate field")
