1	package main
2	
3	// Command-line regression tests for `edgefleet heartbeat health`.
4	//
5	// The domain rules (new-missed arithmetic, rollback detection, baseline
6	// validation) already have focused tests in package edgefleet. These tests
7	// protect what a user actually sees at the real command entry point:
8	//
9	//   - whether --missed-since-seq takes effect at all,
10	//   - the exact terminal output (cumulative missed stays on the first line,
11	//     baseline fields on the second),
12	//   - stdout vs stderr placement (health findings vs usage errors),
13	//   - and the process exit status (a health finding is not a command failure;
14	//     a bad baseline is).
15	//
16	// The tests re-execute the compiled test binary, which calls main() itself
17	// (see TestMain), so the code under test is the genuine command path — flag
18	// parsing included. Everything runs offline against a temp data directory
19	// with fixed receive/query instants, so no wall-clock waiting or network is
20	// involved.
21	
22	import (
23		"crypto/sha256"
24		"encoding/hex"
25		"errors"
26		"os"
27		"os/exec"
28		"path/filepath"
29		"strings"
30		"testing"
31	)
32	
33	const (
34		// cliTestEnv makes the re-executed test binary run the real main() instead
35		// of the test suite.
36		cliTestEnv = "EDGEFLEET_CLI_TEST_HELPER_PROCESS"
37	
38		// Fixed instants: heartbeats arrive and are queried at known times, so
39		// online status is deterministic without sleeping.
40		cliReceiveAt = "2026-10-01T12:00:00Z"
41		cliQueryAt   = "2026-10-01T12:00:00Z"
42	)
43	
44	// fixture holds a populated, isolated data directory.
45	type fixture struct {
46		t   *testing.T
47		dir string
48	}
49	
50	func TestMain(m *testing.M) {
51		if os.Getenv(cliTestEnv) == "1" {
52			// Run the genuine command entry point and let its own os.Exit calls
53			// determine the helper process status.
54			main()
55			os.Exit(0)
56		}
57		os.Exit(m.Run())
58	}
59	
60	// runCLI invokes the re-executed binary with the given arguments. stdin is
61	// fed to the command (used by `heartbeat submit`). It returns the captured
62	// stdout, stderr and exit code.
63	func runCLI(t *testing.T, dir, stdin string, args ...string) (string, string, int) {
64		t.Helper()
65		cmd := exec.Command(os.Args[0], args...)
66		cmd.Stdin = strings.NewReader(stdin)
67		// Keep HOME inside the temp area too, so a missing --data-dir could never
68		// touch the developer's real ~/.edgefleet.
69		cmd.Env = append(os.Environ(),
70			cliTestEnv+"=1",
71			"HOME="+dir,
72			"EDGEFLEET_DATA_DIR="+filepath.Join(dir, "env-data"),
73		)
74		var out, errOut strings.Builder
75		cmd.Stdout = &out
76		cmd.Stderr = &errOut
77		err := cmd.Run()
78		code := 0
79		if err != nil {
80			var exitErr *exec.ExitError
81			if errors.As(err, &exitErr) {
82				code = exitErr.ExitCode()
83			} else {
84				t.Fatalf("failed to run helper binary: %v", err)
85			}
86		}
87		return out.String(), errOut.String(), code
88	}
89	
90	// submitBatch stores one JSON array via the real submit command.
91	func submitBatch(t *testing.T, dir, json string) {
92		t.Helper()
93		out, errOut, code := runCLI(t, dir, json,
94			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
95		if code != 0 {
96			t.Fatalf("submit exited %d: stderr=%q stdout=%q", code, errOut, out)
97		}
98	}
99	
100	// health runs the health command with the common fixed query time.
101	func health(t *testing.T, f *fixture, args ...string) (string, string, int) {
102		t.Helper()
103		full := append([]string{"heartbeat", "health", "--data-dir", f.dir, "--at", cliQueryAt}, args...)
104		return runCLI(t, f.dir, "", full...)
105	}
106	
107	// outputLines splits stdout into lines, treating a trailing newline as no
108	// extra empty line.
109	func outputLines(s string) []string {
110		s = strings.TrimRight(s, "\n")
111		if s == "" {
112			return nil
113		}
114		return strings.Split(s, "\n")
115	}
116	
117	// newFixture creates a temp data directory with three nodes:
118	//
119	//	mono:   seq 1/2/3, cumulative missed 12/13/14, version 1.26.0
120	//	reset:  seq 1/2/3, cumulative missed 12/5/14 (counter reset), version 1.25.0
121	//	gappy:  seq 1/3 (seq 2 never saved), missed 0/4, version 1.26.0
122	//
123	// Latest collection time is one second before cliQueryAt, so every node is
124	// online at the query instant.
125	func newFixture(t *testing.T) *fixture {
126		t.Helper()
127		f := &fixture{t: t, dir: t.TempDir()}
128	
129		submitBatch(t, f.dir, `[
130		  {"node":"mono","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.26.0","height":101,"missed":12},
131		  {"node":"mono","seq":2,"collected_at":"2026-10-01T11:59:58Z","version":"1.26.0","height":102,"missed":13},
132		  {"node":"mono","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":103,"missed":14}
133		]`)
134		submitBatch(t, f.dir, `[
135		  {"node":"reset","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.25.0","height":201,"missed":12},
136		  {"node":"reset","seq":2,"collected_at":"2026-10-01T11:59:58Z","version":"1.25.0","height":202,"missed":5},
137		  {"node":"reset","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.25.0","height":203,"missed":14}
138		]`)
139		submitBatch(t, f.dir, `[
140		  {"node":"gappy","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.26.0","height":301,"missed":0},
141		  {"node":"gappy","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":303,"missed":4}
142		]`)
143		return f
144	}
