146	func TestCLIHealthBaselineTakesEffect(t *testing.T) {
147		f := newFixture(t)
148	
149		// Baseline cumulative 12, latest cumulative 14, tolerance 2: the two new
150		// missed duties equal the tolerance and must NOT alarm.
151		out, errOut, code := health(t, f,
152			"--node", "mono", "--expected-version", "1.26.0",
153			"--tolerated-misses", "2", "--missed-since-seq", "1")
154		if code != 0 {
155			t.Fatalf("health query with a valid baseline must succeed, exit=%d stderr=%q", code, errOut)
156		}
157		if errOut != "" {
158			t.Errorf("health findings belong on stdout; stderr should be empty, got %q", errOut)
159		}
160	
161		lines := outputLines(out)
162		if len(lines) != 2 {
163			t.Fatalf("baseline query must print two lines, got %d: %q", len(lines), out)
164		}
165	
166		// The latest heartbeat (greatest seq) is still what the first line shows,
167		// and missed there stays the cumulative value (14), never the new count.
168		first := lines[0]
169		for _, want := range []string{
170			"node=mono", "status=online", "seq=3", "version=1.26.0",
171			"height=103", "missed=14", "collected_at=2026-10-01T11:59:59Z",
172		} {
173			if !strings.Contains(first, want) {
174				t.Errorf("first line %q missing %q", first, want)
175			}
176		}
177		if strings.Contains(first, "missed=2 ") || strings.HasSuffix(first, "missed=2") {
178			t.Errorf("first line must keep cumulative missed=14, not the new count: %q", first)
179		}
180		if strings.Contains(first, "above tolerance") {
181			t.Errorf("new=2 with tolerance 2 must not alarm: %q", first)
182		}
183	
184		// The baseline basis is stated separately on the second line.
185		wantSecond := "baseline_seq=1 baseline_missed=12 new_missed=2 tolerated_misses=2"
186		if lines[1] != wantSecond {
187			t.Errorf("second line = %q, want %q", lines[1], wantSecond)
188		}
189	}
