191	func TestCLIHealthWithoutBaselineKeepsCumulativeRule(t *testing.T) {
192		f := newFixture(t)
193	
194		// Same history, no baseline: the judgement uses the cumulative 14 and the
195		// tolerance 2, so it alarms — and no baseline explanation is printed.
