		case r >= 0xDC00 && r <= 0xDFFF:
			if !pendingHigh {
				return fmt.Errorf("node contains an unpaired low surrogate in a Unicode escape")
			}
			pendingHigh = false
		default:
			if pendingHigh {
				return fmt.Errorf("node contains an unpaired high surrogate in a Unicode escape")
			}
		}
	}
