	good := recordJSON(`"good"`)
	bad := recordJSON(`"bad` + "\xff" + `"`)
	for _, tc := range []struct {
		name  string
		input string
		pos   string
	}{
		{"bad first", "[" + bad + "," + good + "]", "record 1"},
		{"bad second", "[" + good + "," + bad + "]", "record 2"},
